class PolarCamera
{
  let m_camD;
  m_CamAngleX = -0.4;
  m_CamAngleY = -0.5;
  let m_camDir;
  let m_camDelta;
  let m_camPos;
  constructor()
  {
    update(0,0);
  }
  Settings()
  {
    return "new constructor( new PVector(" + m_camPos.x +", "
          +  m_camPos.y +", " + m_camPos.z + "), "
          + m_CamAngleX + ", " +  m_CamAngleY + ") ";
  }
  constructor( d, cax, cay, cd )
  {
    m_camD= d;
    m_CamAngleX = cax;
    m_CamAngleY = cay;
     m_camDelta = cd;
    update( 0,0);
  }
  function update(dy, dz)
  {
     m_CamAngleX += dy;
     m_CamAngleY += -dz;
    rotate(m_CamAngleX, m_CamAngleY);              
  }
  function forward(v )
  {
    m_camD +=v*0.25* m_camDelta;
     rotate(m_CamAngleX, m_CamAngleY);              
  }
   function rotate(ang, angy )
   {
     m_camDir = new PVector();
     m_camDir.x = sin(ang)*cos(angy);
     m_camDir.z = cos(ang)*cos(angy);
     m_camDir.y = sin(angy);
     m_camPos = new PVector(0.0,0.0,0.0);
     m_camPos.x = -m_camDir.x*m_camD;
     m_camPos.z = -m_camDir.z*m_camD;     
     m_camPos.y =-m_camDir.y*m_camD +.25;
     m_camDir.normalize();

   }

  function side(v )
  {
    m_camD +=(v*0.25* m_camDelta);
   rotate(m_CamAngleX, m_CamAngleY);              
  }
}
