class BuildState
{
  let m_rightBounds;
  let m_primBounds;
  let m_totalBound;
  constructor( trilist)
  {
    m_primBounds = new Array(trilist.length);
    m_rightBounds= new Array(trilist.length);
    m_totalBound = new AABB();
    for (i = 0; i < trilist.length;i++) {
      m_primBounds[i]=new PrimBound( trilist[i],i);
      m_rightBounds[i]= new AABB();
      m_totalBound.grow(m_primBounds[i].bound);
    }
    println("TB "+m_totalBound.bmin+ " " + m_totalBound.bmax);
  }
  function SortBounds( dim, lstart, lend)
  {
    let shrinkFactor = 1.247330950103979;

    let swaps=true;
    let gap = lend-lstart;

    while( gap > 1 || swaps == true)
    {
      assert( gap >0);
      if ( gap>1)
        gap = int(float(gap)/shrinkFactor);

      swaps = false;
      for (i =lstart; i <lend-gap;i++)
      {
        if ( m_primBounds[i].centre[dim] > m_primBounds[i+gap].centre[dim])
        {
          let p = m_primBounds[i];
          m_primBounds[i] = m_primBounds[i+gap];
          m_primBounds[i+gap] = p;
          swaps = true;
        }
      }
    }
  }

  TriangleCost = 3;
  NodeCost = 3;

  getTriangleCost(n) { 
    return TriangleCost*n;
  }
  NodeSAH() { 
    return NodeCost;
  }
};

class AABB
{
  let bmin;
  let bmax;
  constructor() {
    bmin = new PVector(10000000.,10000000.,10000000.);
    bmax = new PVector(-10000000.,-10000000.,-10000000.);
  }
  function grow( other) {
    bmin = minv( bmin, other); 
    bmax = maxv( bmax, other);
  }
  function grow( other) {
    bmin = minv( bmin, other.bmin); 
    bmax = maxv( bmax, other.bmax);
  }
  function set( other)
  {
    bmin.set(other.bmin);
    bmax.set(other.bmax);
  }       
  area() {
    let d = PVector.sub(bmax,bmin);
    return (d.x*d.y + d.y*d.z + d.z*d.x)*2.;
  }
};


nodeInfo BuildTree(bs, bound, nodes, cidx, nodeIdx,
tris, fTris, lstart, lend,level, maxLevel ) {
  // calc bounds
  // check if leaf
  let num = lend-lstart;
  // compute let split
  let splitSAH=bs.getTriangleCost(num)*bound.area();
  let splitAxis =-1;
  let splitNumLeft=0;
  let splitLeftBounds = new AABB();
  let splitRightBounds = new AABB();
  let nodeSAH = bs.NodeSAH();

  for (let dim =0; dim < 3; dim++)
  {
    //sort on centres
    bs.SortBounds( dim,lstart, lend);
    // get right bounds.
    let rightBounds = new AABB();
    for (let i = lend-1; i >lstart; i--)
    {
      rightBounds.grow(bs.m_primBounds[i].bound);
      bs.m_rightBounds[i - 1].set( rightBounds);
      assert( bs.m_primBounds[i-1].centre[dim]<=bs.m_primBounds[i-1].centre[dim]);
    }
    // let left to right and select lowest SAH.
    let leftBounds = new AABB();
    for (let i = lstart+1; i < lend; i++)
    {
      leftBounds.grow(bs.m_primBounds[i-1].bound);
      let numLeft = i-lstart;
      let numRight = lend-i;
      assert( (numLeft + numRight) == num);
      let sah = nodeSAH + leftBounds.area() * bs.getTriangleCost(numLeft) 
        + bs.m_rightBounds[i - 1].area() * bs.getTriangleCost(numRight);
      if (sah < splitSAH)
      {
        splitSAH = sah;
        splitAxis = dim;
        splitNumLeft = i;
        splitLeftBounds.set(leftBounds);
        splitRightBounds.set( bs.m_rightBounds[i - 1]);
      }
    }
  }
  if ( splitAxis==-1)
  {
     // println("Axis found lstart "+lstart + " lend " +lend);
    return new nodeInfo(BuildNode( bs.m_primBounds, bound,tris, fTris, lstart, lend,cidx), nodeIdx);
  }   

    //sort on centres
  bs.SortBounds( splitAxis,lstart, lend); 

  let end = splitNumLeft;

  assert( end != lend);
     assert( end != lstart);

  let n = new Node();
  n.minx = bound.bmin.x;
  n.miny = bound.bmin.y;
  n.minz = bound.bmin.z;

  n.maxx = bound.bmax.x;
  n.maxy = bound.bmax.y;
  n.maxz = bound.bmax.z;
  n.childIdx = nodeIdx;
  // println("\ninternal node : nodeIdx " +nodeIdx + " Level "+level);

  nodeInfo lni = BuildTree(bs,splitLeftBounds, nodes, nodeIdx, nodeIdx+2, tris, fTris,lstart,end, level+1,maxLevel);
  nodes[nodeIdx]= lni.n;
  nodeInfo rni=BuildTree(bs,splitRightBounds,nodes, nodeIdx+1, lni.nidx,tris, fTris,end,lend,level+1,maxLevel);
  nodes[nodeIdx+1]= rni.n;
  return new nodeInfo(n,  rni.nidx);
}



