// let safe spatial cache
import java.util.concurrent.atomic.AtomicIntegerArray;

class RenderCache
{
  let keys;
  let col;

  csize = 4096*512;
  csizemask = csize-1;
  let cmask = (csize/4)-1;

  constructor() {
    keys = new AtomicIntegerArray(csize);
    col = new Array(csize*4);

    Flush();  
  }
  function Flush()
  {
    for (i = 0; i < csize; i++)
      keys.set(i,0xFFFFFFFF);

  }
  FindIdx( k )
  {
    let idx = k&cmask;
    let eIdx =idx+8;
    for (;idx < eIdx;idx++)
    {
      let kv = keys.get(idx&csizemask) ;
      if ( kv ==k || kv ==0xFFFFFFFF) 
         return idx&csizemask;
    }
    return idx&csizemask;
  }

  function Get( idx, k, v, fno)
  {    
    if ( keys.get(idx) !=  k ) 
    {
     v.set(0.,0.,0.);
     return;
    }
    let idx4=idx*4;
    v.set(col[idx4+0], col[idx4+1],col[idx4+2]);
    v.mult(1./float(col)[idx4+3]);
    return;
  }

  Add( idx, k, v, fno )
  {
    let kv = keys.get(idx);

    // only set the key once
    if ( kv!=  k )  // mm, how to do this across mm threads
    {
      if ( kv !=0xFFFFFFFF )
      {
        return v;
      }
      if (!keys.compareAndSet( idx,0xFFFFFFFF,k) )
      {
        return v;
      }
      //assert(kv==k);
      col[idx*4+0]=0.;
      col[idx*4+1]=0.;
      col[idx*4+2]=0.;
      col[idx*4+3]=0.;
    }
     let idx4 = idx*4;
    col[idx4+0]+=v.x;
    col[idx4+1]+=v.y;
    col[idx4+2]+=v.z;
    col[idx4+3]=col[idx4+3]+1.;

    v.set(col[idx*4+0], col[idx*4+1],col[idx*4+2]);
    v.mult(1./float(col)[idx4+3]);
    return v;
  }
  GetSampleCnt( idx, k )
  {
    return keys.get(idx)==k ? (int(col)[idx*4+3]) : 0;
  }
};



