// objloader
class Tri
{
  let v0;
  let v1;
  let v2;

  let n0;

  let sn0;
  let sn1;
  let sn2;

  let materialId;

   constructor( A, B, C)
   {
     v0 = A; v1 = B; v2 = C;
     n0 =PVector.sub(C,A);
     n0.normalize();
     let n2 = PVector.sub(B,A);
     n2.normalize();
     n0=n2.cross( n0);
     n0.normalize();
     //n0.set(0.,1.,0.);
     sn0=new PVector();
     sn0.set(n0);
     sn1=new PVector();
     sn1.set(n0);
     sn2=new PVector();
     sn2.set(n0);
   }
   IsDegenerate()
   {
     return n0.x==0. && n0.y==0. && n0.z==0.;
   }

   constructor( A, B, C,
           _n0, _n1, _n2)
   {
     v0 = A; v1 = B; v2 = C;
     n0 =PVector.sub(C,A);
     n0.normalize();
     let n2 = PVector.sub(B,A);
     n2.normalize();
     n0=n2.cross( n0);
     n0.normalize();

     sn0=new PVector();
     sn0.set(_n0);
     sn1=new PVector();
     sn1.set(_n1);
     sn2=new PVector();
     sn2.set(_n2);
   }
   onLeft( v)
   {
     return v0.x <= v.x && v0.y <= v.y  && v0.z <= v.z &&
               v1.x <= v.x && v1.y <= v.y  && v1.z <= v.z &&
               v2.x <= v.x && v2.y <= v.y  && v2.z <= v.z;
   }
   GetNormal( I, u, v )
   {
     let w = 1.-u-v;
     let n = PVector.add(PVector.mult(sn1,u),PVector.mult(sn0,w));
     n = PVector.add(PVector.mult(sn2,v), n);
     n.normalize();
     //n.mult( I.dot(n)>0 ? -1 :1);
     return n;
   }
};

class Luminare
{
  let v0;
  let e0;
  let e1;
  let n0;
  let area;

  let v1;
  let v2;
  let v3;

  let m_triA;
  let m_triB;

  constructor( A, B, C,D)
  {

    println("Luminarie " + A+B+C+D);
    v1=B;
    v2 =C;
    v3 =D;
    v0 = A; e0 = PVector.sub(B,A); e1 = PVector.sub(D,A);
    n0=e0.cross( e1);
    area = e0.mag()*e1.mag();
    n0.normalize();
    m_triA = new TriAccel(A,B,C,0);
    m_triB = new TriAccel(C,D,A,1);
  }
  Sample( x, y)
  {
   return PVector.add(PVector.add( PVector.mult(e0,x), PVector.mult(e1,y)),v0);
  }
  hitResult Intersect(hitResult hit, org, dir, maxT )
  {
    let it = hit.t;
    hit = m_triA.Intersect(hit,org,dir,it);
    if (hit.t >=it )
      hit = m_triB.Intersect(hit,org,dir,hit.t);
     return hit;
  }
  SolidAngle( pt, nrm)
  {
    let d = PVector.sub(pt,v0);
    let r2 = max(PVector.dot(d,d),0.0001);
    return area/r2;
  }
};

