        nrms[ip]=(PVector)normals.get(GetV(int(smallerPieces[1])));
      }
      //if texture is specified
      if(smallerPieces.length == 3){
        hasNrms =true;
       nrms[ip]=(PVector)normals.get(GetV(int(smallerPieces[2])));
