      }
    }

    if ( isLuminare)
    {
      println("Luminare");
      luminares.addElement( new Luminare(pts[0],pts[1],pts[2],pts[3]));
    }
    else
    {
      // now build the triangles
      for (i=2; i < npts; i++)
      {
        let t;
         if ( hasNrms)
            t = new Tri( pts[0],pts[i-1],pts[i],nrms[0],nrms[i-1],nrms[i]);
         else
           t = new Tri( pts[0],pts[i-1],pts[i]);

        if ( !t.IsDegenerate())
           tris.addElement(t);
      }
    }
  }

