/* seedx, seedy is point on [0,1]^2.  x, y is point on radius 1 disk */

function to_unit_disk( seedx, seedy, angle) {
  let phi, r;
  let a = 2.*seedx - 1.;   /* (a,b) is now on [-1,1]^2 */
  let b = 2.*seedy - 1.;
  if (a > -b) {     /* region 1 or 2 */
    if (a > b) {  /* region 1, also |a| > |b| */
      r = a;
      phi = (PI*1./4 ) * (b/a);
    }
    else  {  /* region 2, also |b| > |a| */
    r = b;
    phi = (PI*1./4 ) * (2 - (a/b));
    }
  }
  else {        /* region 3 or 4 */
    if (a < b) {  /* region 3, also |a| >= |b|, a != 0 */
        r = -a;
        phi = (PI*1./4 ) * (4 + (b/a));
    }
    else {  /* region 4, |b| >= |a|, but a==0 and b==0 could occur. */
        r = -b;
        if (b != 0)
            phi = (PI*1./4 ) * (6 - (a/b));
          else
              phi = 0;
    }
  }
  let x = (r * cos(phi))*angle;
  let y = (r * sin(phi))*angle;
 let z =sqrt(1.-x*x-y*y);
  return new PVector( x,z,y);  //
}

 function Sobol2(n2,  r2) {
  long n = n2;
  long r = r2;
  for (long  v = 1 << 31L; n != 0L; n >>= 1L, v ^= v >> 1L)
         if ((n & 0x1L) != 0 )
              r ^= v;
  r  = (r &0xFFFFFFFFL);
  return (float(r))/  ( float(0x100000000L)); } 




