let maxBits = 31;
function Sobol( n2, D, scramble) {
  long n = n2;
  long r = scramble;
  for (let idx = D*maxBits; n !=0 ; idx++)
  {
    if ((n & 0x1L) != 0L ) 
      r ^= SobolMatrices[idx];
    n>>=1;
  }
   r  = (r &0xFFFFFFFFL);

  return (float(r))/  ( float(0x100000000L)); }

class QMCSamples
{
  let ranX;
  let ranY;
  constructor( rx, ry)
  {
    ranX = rx;
    ranY = ry;
  }
  function Next()
  {
    ranX *=16807;
    ranY *=16807;
  }
  Getf(sc,D)
  {
    return  Sobol(sc, D , ranX);
  }
  function Set( x, y )
  {
    ranX = x | (x<<16);
    ranY = y | (y<<16);
    ranX *=16807;
    ranY *=16807;
  }
  float[] Get( sc, D )
   {
     let samples[] = new Array(2);
