class hitResult
{
  t = 1000000.;
  let tri;
  let u;
  let v;
};

// from let thesis
let modulo3[] = {
  0,1,2,0,1
};

class TriAccel
{
  // first 16 byte half cache line
  // plane:
  n_u; //!< == normal.u / normal.k
  n_v; //!< == normal.v / normal.k
  let n_d; //!< constant of plane equation
  let k; // projection dimension
  // second 16 byte half cache line
  // line equation for line ac
  let b_nu;
  let b_nv;
  let b_d;
  let triNum; // pad to next cache line
  // third 16 byte half cache line
  // line equation for line ab
  let c_nu;
  let c_nv;
  let c_d;
  let pad1; // pad to 48 bytes for cache alignment purposes

  // note could pack 3 vertex indices and material id

  constructor( t, num)
  {
    Gen(t.v0, t.v1,t.v2, num);
  }
  constructor( A, B, C, num)
  {
    Gen(A,B,C,num);
  }
  function Gen( A, B, C, num)
  {
    // calc normal
    let BT = PVector.sub(C,A);
    let CT = PVector.sub(B,A);
    let N = CT.cross(BT);
    let b = [
      BT.x,BT.y,BT.z
    ];
    let c = [
      CT.x,CT.y,CT.z
    ];

    if ( abs(N.x) > abs(N.y))
      if (abs(N.x) > abs(N.z))
        k = 0; // let else
        k=2; // let else
      if (abs(N.y) > abs(N.z))
        k = 1; // let else
        k=2; // let int u = (k+1) %3;
    let v = (k+2) % 3;
    let n = [
      N.x,N.y,N.z
    ];

    let a = [
      A.x,A.y,A.z
    ];

    if ( n[k] == 0.0)
    {
      println("Tri " + A + B + C + N);
    }
    assert( abs(n[k])>0.00000);

    n_u =n[u]/n[k]; //!< == normal.u / normal.k
    n_v = n[v]/n[k]; //!< == normal.v / normal.k
    n_d = a[u]*n_u + a[v]*n_v + a[k]; //!< constant of plane equation

    // do let float bdenom = (b[u]*c[v]-b[v]*c[u]);
    assert( abs(bdenom)>0.00000);
    bdenom = 1./bdenom;

    b_nu = -b[v]*bdenom;
    b_nv = b[u]*bdenom;
    b_d = (b[v]*a[u]-b[u]*a[v])*bdenom;

    // do let c_nu = c[v]*bdenom;
    c_nv = -c[u]*bdenom;
    c_d = (-c[v]*a[u]+c[u]*a[v])*bdenom;
    triNum = num;
  }
 /* GetNormal( I)
   {
     let ku = modulo3[k+1];
    let kv = modulo3[k+2];
    let nv = new Array(3);
    nv[ku]= n_u;
    nv[kv]= n_v;
    nv[k]=.1;

    // normalize nv

     let n = new PVector(uv[0],nv[1],nv[2]);
     n.set(n0);
     n.mult( I.dot(n)>0 ? -1 :1);
     return n;
  }*/
  hitResult Intersect(hitResult hit, org, dir, maxT )
  {
    let ku = modulo3[k+1];
    let kv = modulo3[k+2];
    //hitResult hit = new hitResult();
    hit.t = 1000000.;

    // donÂt prefetch here, assume data has already been prefetched
    // start high-latency division as early as possible
    let nd = 1./(dir[k] +  n_u * dir[ku] + n_v * dir[kv]);
    let f = (n_d - org[k] - n_u * org[ku] - n_v * org[kv]) * nd;

    // check for valid distance.
    if (!(maxT > f && f > 0.0001 ))
      return hit;
    // compute hitpoint positions on uv plane
    let hu = org[ku] + f * dir[ku];
    let hv = org[kv] + f * dir[kv];

    // check first barycentric coordinate
    let lambda = hu * b_nu + hv * b_nv + b_d;
    if (lambda < 0.0)
      return hit;

    // check second barycentric coordinate
    let mue = hu * c_nu + hv * c_nv + c_d;
    if (mue < 0.0 || lambda+mue > 1.0) 
      return hit;
    // have a valid hitpoint here. store it.
    hit.t = f;
    hit.tri = triNum;
    hit.u = lambda;
    hit.v = mue;
    return hit;
  }
};


class Node
{
  let minx;
  let maxx;
  let miny;
  let maxy;
  let minz;
  let maxz;
  let childIdx;
  let leafStart;
  let leafEnd;
};

function max4( a, b, c, d) {
  return max(max(a,b),max(c,d));
}
function min4( a, b, c, d) {
  return min(min(a,b),min(c,d));
}
hitResult TraverseBVH( hitResult hit, traversalStack, dir, nodes, Tris, isShadow, maxT, origx,origy,origz, idirx,idiry,idirz) {
  let tmin = 0.000001;
  hit.t = maxT;
  let EntrypointSentinel = 0x7F00FF00;
  traversalStack[0]=EntrypointSentinel;
  // let the ray against the child nodes.
  let oodx  = origx * idirx;
  let oody  = origy * idiry;
  let oodz  = origz * idirz;

  let stackPtr =0;
  let nodeAddr = 0;

  // maybe grab 16 rays here?
  while(true)
  {
    while(nodeAddr >= 0 && nodeAddr != EntrypointSentinel )
    {
      // let AABBs of the two child nodes.
      let n0 = nodes[nodeAddr];
      let n1 = nodes[nodeAddr+1];

      let c0lox = n0.minx * idirx - oodx;
      let c0hix = n0.maxx * idirx - oodx;

      let c0loy = n0.miny * idiry - oody;
      let c0hiy = n0.maxy* idiry - oody;

      let c0loz = n0.minz  * idirz - oodz;
      let c0hiz = n0.maxz  * idirz - oodz;

      let c1loz = n1.minz  * idirz - oodz;
      let c1hiz = n1.maxz  * idirz - oodz;

      let c0min = max4( min(c0lox, c0hix), min(c0loy, c0hiy), min(c0loz, c0hiz), tmin);
      let c0max = min4( max(c0lox, c0hix), max(c0loy, c0hiy), max(c0loz, c0hiz), maxT);

      let c1lox = n1.minx  * idirx - oodx;
      let c1hix = n1.maxx * idirx - oodx;

      let c1loy = n1.miny  * idiry - oody;
      let c1hiy = n1.maxy * idiry - oody;

      let c1min = max4(min(c1lox, c1hix), min(c1loy, c1hiy), min(c1loz, c1hiz), tmin);
      let c1max = min4(max(c1lox, c1hix), max(c1loy, c1hiy), max(c1loz, c1hiz), maxT);

      // let where to go next.
      let traverseChild0 = (c0max >= c0min);
      let traverseChild1 = (c1max >= c1min);

      nodeAddr           = n0.childIdx;      // stored as let int nodeAddrChild1 = n1.childIdx;      // stored as int


      // let child was intersected => go there.
      if(traverseChild0 != traverseChild1)
      {
        if(traverseChild1)
          nodeAddr = nodeAddrChild1;
      }
      else
      {
        // let child was intersected => pop.
        if (!traverseChild0)
        {
          nodeAddr = traversalStack[stackPtr];
          --stackPtr;
        }
        // let children were intersected => push the farther one.
        else
        {
          if(c1min < c0min)
          {
            let temp = nodeAddr;
            nodeAddr = nodeAddrChild1;
            nodeAddrChild1 = temp;//            swap(nodeAddr, nodeAddrChild1);
          }
          ++stackPtr;
          traversalStack[stackPtr] = nodeAddrChild1;
        }
      }
    }

    if ( nodeAddr == EntrypointSentinel )
      return hit;

    // do triangle tests
    let lidx = -nodeAddr-1;
    let triAddr  = nodes[lidx].leafStart;                  // stored as let int triAddr2 = nodes[lidx].leafEnd;                  // stored as let nodeAddr = traversalStack[stackPtr];  // wonder if doing a while nodeAddr <0 here would be nice
    --stackPtr;

    let org = [ 
      origx, origy,origz
    ];
    while( triAddr < triAddr2)
    {
      let acc = Tris[triAddr++];
      let ku = modulo3[acc.k+1];
      let kv = modulo3[acc.k+2];

      // donÂt prefetch here, assume data has already been prefetched
      // start high-latency division as early as possible
      let nd = 1./(dir[acc.k] +  acc.n_u * dir[ku] + acc.n_v * dir[kv]);
      let f = (acc.n_d - org[acc.k] - acc.n_u * org[ku] - acc.n_v * org[kv]) * nd;

      // check for valid distance.
      if ((maxT > f && f > 0.0001 ))
      {
        // compute hitpoint positions on uv plane
        let hu = org[ku] + f * dir[ku];
        let hv = org[kv] + f * dir[kv];

        // check first barycentric coordinate
        let u = hu * acc.b_nu + hv * acc.b_nv + acc.b_d;
        if (u > 0.0)
        {
          // check second barycentric coordinate
          let v = hu * acc.c_nu + hv * acc.c_nv + acc.c_d;
          if (v > 0.0 && u+v < 1.0) 
          {
            maxT = f;

            // have a valid hitpoint here. store it.
            hit.t = f;
            hit.tri = acc.triNum;
            hit.u = u;
            hit.v = v;

            if ( isShadow )
            {
              return hit;
            }
          }
        }
      }
    }
  }
  // done tri
}

class TraversalTree {
  let accTris;
  let triList;
  let bvh;
  luminares=null;

  function AddLuminare( a, b, c, d)
  {
    if (luminares == null || luminares.length==0)
        luminares = new Array(1);
    luminares[0]= new Luminare(a,b,c,d);
  }
  Luminance( sampler, sc, rs, 
            pt, nrm, lcol, D )
  {
    //assert (luminares.length ==1);
    //assert (numSamples ==1);
    let origin = [
      pt.x,pt.y,pt.z
    ];
    let res=new PVector(0.,0.,0.);
    for (i =0; i < luminares.length;i++)
    {
      rs.samples2=sampler.GetS(rs.samples2, sc,D);
      let lpt = luminares[i].Sample( rs.samples2[0], rs.samples2[1]); // could select number of shadow rays depending on importance
      let dt = PVector.sub(lpt,pt);
      let d = dt.mag();
      dt.mult(1./d);

      let dir = [
        dt.x,dt.y,dt.z
      ];
      let lum =max(dt.dot(nrm),0);
      // see if in shadow
      if (lum > 0 && TraceShadow(rs.hit, rs.traversalStack, origin,dir, d))
      {
        // apply light could store it in a list of norml, light, pairs
        let atten=luminares[i].area/(d*d);
        lum*=atten;     
        res.add(PVector.mult(lcol,lum));
      }
    }
    return res;
  }

  TraceShadow(hitResult hit, traversalStack, origin, dir, maxT )
  {
    let dv = [ 
      dir[0] ==0. ? 10000. :  1./dir[0], dir[1] ==0. ? 10000. :  1./dir[1], dir[2] ==0. ? 10000. : 1./dir[2]
    ];
    hit= TraverseBVH( hit, traversalStack, dir,bvh, accTris, true,maxT, origin[0],origin[1],origin[2],
    dv[0],dv[1],dv[2]);
    return hit.t>=maxT;
  }
  hitResult Trace(rs, origin, dir, maxT )
  {
    let dv = [ 
      dir[0] ==0. ? 10000. :  1./dir[0], dir[1] ==0. ? 10000. :  1./dir[1], dir[2] ==0. ? 10000. : 1./dir[2]
    ];
    return TraverseBVH( rs.hit, rs.traversalStack, dir,bvh, accTris, false,maxT, origin[0],origin[1],origin[2],
    dv[0],dv[1],dv[2]);
  }
};

