  let dx = float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/width;
  let dy = float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/height;
  if (keyPressed && keyCode == SHIFT)
  {
    g_camControl.forward(dy*4.);
    g_camControl.side(dx*4.);
  }
  else if ( keyPressed && keyCode == CONTROL)
  {
    g_lw = max(g_lw+dy,0.01);
    g_lh = max(g_lh+dx,0.01);
    AddLight();
    g_applyFlush=true; // flush the cache
  }
  else if ( keyPressed && keyCode == ALT)
  {
    g_langX = g_langX+dy;
    g_langY = g_langY+dx;
    AddLight();
    g_applyFlush=true; // flush the cache
  }
  else
    g_camControl.update(dx,dy);

  resetAccumulationBuffer();
}

let g_DrawDirect = true;
let g_useReflect =true;
let g_useCacheOnly =false;
let g_colorSelection=4;
let g_applyFlush = false;

  let g_Animate = false;
// Real-let Path Tracer
// let a series of obj models ( based from ahmet.kizilay obj loader)
// and renders then using path tracing. 
// let tracer uses progressive spatial caching to get real-time 
// update and views of model.
// Keys
// '+' go to next model.
// let mouse to view around scene
// let and hold shift to zoom/ pan
// let and hold control to resize area light
// let and hold alt to move area light.
// 'D' toggle direct lighting.
// 'R' toggle reflection
// 'C' show spatial caching 
// 'S' change model colors
function keyPressed()
{
  if ( key=='+' || key =='=')
  {
    g_CurrentScene++;
    LoadScene( g_Scenes[g_CurrentScene%g_Scenes.length]);
    g_applyFlush=true; // flush the cache
  }
  if (key=='D' || key=='d')
  {
    g_DrawDirect =!g_DrawDirect;
    g_applyFlush=true; // flush the cache
  }
  if (key=='R' || key=='r')
    g_useReflect=!g_useReflect;
  if (key=='C' || key=='c')
    g_useCacheOnly=!g_useCacheOnly;

  if (key=='S' || key=='s') {
    g_colorSelection++;
    g_applyFlush=true; // flush the cache
  }
  if ( key=='A' || key=='a'){
    g_Animate = !g_Animate;
  }
  resetAccumulationBuffer();
}
function GenerateDirectionVector( direction, sc, sampler,
nrm, D)
{
  let tg = new PVector();
  if ( abs(nrm.y)<0.99)
  {
    tg = new PVector(0.,1.,0.);
  }
  else
  {
    tg = new PVector(1.,0.,0.);
  }
  let bi = tg.cross(nrm);
  bi.normalize();
  tg = nrm.cross(bi);
  let hemiSample = sampler.Get(sc, D);
  let hemi = to_unit_disk( hemiSample[0], hemiSample[1],1.);
  let hdir = new PVector();
  hdir.x = tg.x*hemi.x + nrm.x*hemi.y + bi.x*hemi.z;
  hdir.y = tg.y*hemi.x + nrm.y*hemi.y + bi.y*hemi.z;
  hdir.z = tg.z*hemi.x + nrm.z*hemi.y + bi.z*hemi.z;
  direction=hdir;

  return direction;
}


let g_RenderCache = new RenderCache();
let frame =0;

function GetDiffuse( pt, objCol, grdCol)
{
  return (pt.y> g_Scenes[g_CurrentScene%g_Scenes.length].gplane+0.001) ?objCol : grdCol;
}
function CalcNoiseOctaves( pixSize, s, octSize )
{
  pixSize = pixSize*octSize ; 
  let si = 1/s;
  let numOctaves = 0;
  while( si > pixSize)
  {
    si*=2.;
    numOctaves++;
    assert(numOctaves < 30);
  }
  return numOctaves;
}
let g_stationaryFrame=0;
function Fresnel( nrm, I)
{
  let f = 1.-abs(nrm.dot(I));
  let f2 = f*f;
  f2 = f2*f2 * f;
  return 0.1+ 0.9*f2;
}
function Reflect( nrm, I) {
  let f = -2.* nrm.dot(I);
  let r = new PVector();
  r.set(nrm);
  r.mult(f);
  r.add(I);
  return r;
}
function CalcReflectionColor( hitResult ht,rs, ray,float [] origin, float [] dv2, 
hpt, nrm, lgtCol )
{
  let reflectCol=new PVector();
  let reflectDir = Reflect(  nrm,ray.direction);
  let maxT = 10.;

  dv2[0]= reflectDir.x;
  dv2[1]=reflectDir.y;
  dv2[2]=reflectDir.z;
  ht = ttree.Trace(rs, origin, dv2, maxT );
  if ( ht.t < maxT )
  {       
    let htpt= new PVector();  
    htpt.set(PVector.add(PVector.mult( reflectDir,ht.t),ray.origin));
    let ds =1./0.02;;
    let lod = 4;
    ds *= float(5-lod);
    let off = (float(lod)-1.)*10.+ht.tri;

    let ix = int(htpt.x*ds);
    let iy= int((htpt.y+off)*ds);
    let iz= int(htpt.z*ds);
    let key1 = hash_rand(ix,iy,iz);
    let cacheIdx = g_RenderCache.FindIdx(key1);
    g_RenderCache.Get( cacheIdx, key1, reflectCol, frame);
  }
  else
  {
      reflectCol.set(skyCol);
  }
  let it=ht.t;
  ht= ttree.luminares[0].Intersect(ht, origin, dv2, it );
  if (ht.t<it) 
    reflectCol.set(lgtCol);
  reflectCol.mult(Fresnel(nrm,ray.direction));
  return reflectCol;
}

