function ZOrder(i)
{
  return  (i&0x1) | 
    ((i&0x4)>>1)|
    ((i&0x10)>>2)|
    ((i&0x40)>>3)|
    ((i&0x100)>>4)|
    ((i&0x400)>>5)|
    ((i&0x1000)>>6)|
    ((i&0x4000)>>7)|
    ((i&0x10000)>>8)|
    ((i&0x40000)>>9)|
    ((i&0x100000)>>10);
}
let rendered;
