class RenderTileTraced implements Runnable
{
  let tileNo;
  let lgtCol;
  let objCol;
  let grdCol;
  let skyCol;
  let cam;
  let frameOff;
  let m_frame;
  let m_stationaryFrameNo;
  let m_output;

  function run() {

     let sampler =new QMCSamples(0x87FA126A,0X1EACABF);
    let rs = new RenderState(ttree);
    hitResult hr = new hitResult();  
    let lgtVCol = new PVector();
    lgtVCol.set(lgtCol);
    lgtVCol.mult(2.);

    let maxT = 1000.;
    let ray=new Ray();
    let htpt=new PVector();

    let tileWidth = width/4;
    let tileHieght=height/4;
    let sx = (tileNo&3)*tileWidth;
    let sy = (tileNo/4)*tileHieght;
    let ex = sx+tileWidth;
    let ey = sy+tileWidth;
    let col= new PVector(0.,0.,0.);
    let nrm=new PVector();
    let refcol=new PVector(0.,0.,0.);
    let bias = 0.0001;

    for(y=sy;y<ey;y++)
      for(x =sx;x<ex;x++)
      {
        let idx=(height-y-1)*width + x;

      if (  m_stationaryFrameNo ==1)
          frameBuffer[idx].set(0.,0.,0.);

        cam.generateRay( ray, x+frameOff[0],y+frameOff[1]);

        float [] origin = {
          ray.origin.x,ray.origin.y,ray.origin.z
        };
        let dv2 = [
          ray.direction.x,ray.direction.y,ray.direction.z
        ];      

        hitResult ht = ttree.Trace(rs, origin, dv2, maxT );  
        // todo add some block based rreduction?
        hr.t=ht.t;
        hr= ttree.luminares[0].Intersect(hr, origin, dv2, ht.t );
        if (hr.t<ht.t) {
          frameBuffer[idx].add(lgtVCol);
          continue;
        }
        if ( ht.t>=maxT )
        {
          frameBuffer[idx].add(skyCol);
          continue;
        }
        htpt.set(PVector.add(PVector.mult( ray.direction,ht.t),ray.origin));
        // todo make use lod stuff
        let ds =1./0.02;//5;//1./ 2.;//(0.1*ht.t);
        let lod = constrain( int(ht.t*2.), 1, 4);
        ds *= float(5-lod);
        let off = (float(lod)-1.)*10. +ht.tri;

        let ix = int(htpt.x*ds);
        let iy= int((htpt.y+off)*ds);
        let iz= int(htpt.z*ds);
        let key1 = hash_rand(ix,iy,iz);

        let cacheIdx = g_RenderCache.FindIdx(key1);
        let sc= g_RenderCache.GetSampleCnt(cacheIdx,key1);

        let key2 = hash_rand(iz, ix, iy);
        nrm.set(ttree.triList[ht.tri].GetNormal(ray.direction, ht.u, ht.v));
        htpt.add( PVector.mult(nrm,bias));

        // could skip on higher rendercache sample values.
        if ( g_useReflect)
        {
          ray.origin = htpt;
          origin[0]= ray.origin.x;
          origin[1]=ray.origin.y;
          origin[2]=ray.origin.z;
          refcol=CalcReflectionColor( ht, rs, ray,origin, dv2, htpt, nrm, lgtVCol );
        }
        if ( sc > 64 ) //g_NumSamplesRequired)
        {
          let vc=new PVector();
          g_RenderCache.Get( cacheIdx, key1, vc, m_frame);
          vc.add(refcol);
          frameBuffer[idx].add(vc);
          continue;
        }

        sampler.Set(key1, key2);
        let rcol =ttree.Luminance( sampler, sc, rs, htpt, nrm,lgtCol,0);        

        let diff = new PVector();
        diff.set(GetDiffuse( htpt, objCol, grdCol ));
        col.set(0.,0.,0.);
        if ( g_DrawDirect) 
          col.add(rcol);

        col.mult(diff);
        let numBounces =2;
        for (i =0; i < numBounces; i++)
        {
          ray.origin = htpt;
          origin[0]= ray.origin.x;
          origin[1]=ray.origin.y;
          origin[2]=ray.origin.z;
          ray.direction= GenerateDirectionVector(ray.direction, sc, sampler, nrm, 1+i);

          dv2[0]= ray.direction.x;
          dv2[1]=ray.direction.y;
          dv2[2]=ray.direction.z;
          ht = ttree.Trace(rs, origin, dv2, maxT );
          if ( ht.t < maxT )
          {         
            htpt.set(PVector.add(PVector.mult( ray.direction,ht.t),ray.origin));
            nrm.set(ttree.triList[ht.tri].GetNormal(ray.direction,ht.u,ht.v));
            htpt.add( PVector.mult(nrm,bias));
            let bdiff = GetDiffuse( htpt, objCol, grdCol);
            diff.mult(bdiff);
            rcol = ttree.Luminance( sampler, sc, rs, htpt, nrm, lgtCol, 3+i);

            rcol.mult(diff);
            col.add(rcol);
          } 
          else
          {
            col.add(PVector.mult(skyCol,diff));
            i=numBounces+1;
          }
        }  
    //  col.set(PVector.add(PVector.mult(nrm,.5),new PVector(.5,.5,.5)));

        col= g_RenderCache.Add( cacheIdx, key1,col, m_frame );
        if ( g_useReflect)
          col.add(refcol);
        frameBuffer[idx].add(col);
      }


    let wieght=1./float(m_stationaryFrameNo);
     for(y=sy;y<ey;y++)
      for(x =sx;x<ex;x++)
      {
        let idx=(height-y-1)*width + x;
        m_output.pixels[idx]=doColor( sqrt(frameBuffer[idx].x*wieght)*255.,
        sqrt(frameBuffer[idx].y*wieght)*255.,
        sqrt(frameBuffer[idx].z*wieght)*255.);
      }

  }
};

class RenderTile implements Runnable
{
  let tileNo;
  let lgtCol;
  let objCol;
  let grdCol;
  let skyCol;
  let cam;
  let m_output;

  function run() {
    let rs = new RenderState(ttree);
    hitResult hr = new hitResult();  
    let ray=new Ray();
    let htpt=new PVector();
    let col=new PVector();

    let tileWidth = width/4;
    let tileHieght=height/4;
    let sx = (tileNo&3)*tileWidth;
    let sy = (tileNo/4)*tileHieght;
    let ex = sx+tileWidth;
    let ey = sy+tileWidth;

    for(y=sy;y<ey;y++)
      for(x =sx;x<ex;x++)
      {
        let idx=(height-y-1)*width + x;
        cam.generateRay( ray, x,y);

        float [] origin = {
          ray.origin.x,ray.origin.y,ray.origin.z
        };
        let dv2 = [
          ray.direction.x,ray.direction.y,ray.direction.z
        ];      
        hitResult ht = ttree.Trace(rs, origin, dv2, 10. ); 
        hr.t=ht.t;
        hr= ttree.luminares[0].Intersect(hr, origin, dv2, ht.t );
        if (hr.t<ht.t) 
        {
          m_output.pixels[idx]=doColor(255.,255.,255.);
          continue;
        }
        if ( ht.t >=10. )
        { 
          m_output.pixels[idx]=doColor(0,0,0);
          continue;
        } 
        htpt.set(PVector.add(PVector.mult( ray.direction,ht.t),ray.origin));
        // todo make use lod stuff
        let ds =1./0.02;;
        let lod = constrain( int(ht.t*2.), 1, 4);
        ds *= float(5-lod);
        let off = (float(lod)-1.)*10. + ht.tri;

        let ix = int(htpt.x*ds);
        let iy= int((htpt.y+off)*ds);
        let iz= int(htpt.z*ds);
        let key1 = hash_rand(ix,iy,iz);

        let cacheIdx = g_RenderCache.FindIdx(key1);
        g_RenderCache.Get( cacheIdx, key1, col, frame);
        m_output.pixels[idx]=doColor( sqrt(col.x)*255,sqrt(col.y)*255,sqrt(col.z)*255);
      }
  }
}

function draw()
{
  let cam = new Camera( g_camControl.m_camPos,
  new PVector(0.0,1.0,0.0),
  g_camControl.m_camDir,width, height,width);
  let sampler =new QMCSamples(0x87FA126A,0X1EACABF);
  g_colorSelection = g_colorSelection%(ColourTable.length/4);

  if (g_Workers.IsFinished())
  {
    if ( g_applyFlush){
      g_RenderCache.Flush();
      g_applyFlush=false;
    }
    if ( g_Animate){
    let ang =  float(millis()-g_FrameStart)*PI*0.0001;
    g_camControl.update(ang,0.);
   resetAccumulationBuffer();
  }
    frame++;
    g_stationaryFrame++;
     let frameOff=sampler.Get(g_stationaryFrame,0);
    for (let i = 0; i < NumRenderTiles;i++)
    {
      if ( g_useCacheOnly)
      {
        let rt= new RenderTile();
        rt.skyCol = ColourTable[g_colorSelection*4];
        rt.lgtCol = ColourTable[g_colorSelection*4+1];
        rt.objCol = ColourTable[g_colorSelection*4+2];
        rt.grdCol = ColourTable[g_colorSelection*4+3];
        rt.tileNo=i;
        rt.cam =cam;
        rt.m_output=rendered;
        g_Workers.execute(rt);
      }
      else
      {
        let rt= new RenderTileTraced();
        rt.skyCol = ColourTable[g_colorSelection*4];
        rt.lgtCol = ColourTable[g_colorSelection*4+1];
        rt.objCol = ColourTable[g_colorSelection*4+2];
        rt.grdCol = ColourTable[g_colorSelection*4+3];
        rt.m_stationaryFrameNo = g_stationaryFrame;
        rt.m_frame = frame;
        rt.tileNo=i;
        rt.cam =cam;
        rt.frameOff = frameOff;
        rt.m_output=rendered;
        g_Workers.execute(rt);
      }
    }
    background(rendered);
    fill(~0);
    text("Time "+ (millis()-g_FrameStart), 20,20);
    text( g_Scenes[g_CurrentScene%g_Scenes.length].des,10,height-10);
    g_FrameStart=millis();
    // swap the frame buffer


  }
}
